using System;
using System.Threading;
using Cysharp.Threading.Tasks;

namespace LiteGame
{
    /// <summary>一次入场操作的寿命阶段（由流程/阶段按顺序推进，不引入独立状态机）。</summary>
    internal enum RoomFlowPhase
    {
        Requesting,
        QueuedMatch,
        Joining,
        QueuedBattle,
        Running,
        Cleaning,
        Cleaned,
    }

    /// <summary>一次入场操作的句柄：阶段、独立取消、页面注册、待接管会话与清理完成信号。</summary>
    internal sealed class RoomFlowOperation : IDisposable
    {
        private readonly CancellationTokenSource _cancellation;
        private readonly Action<RoomFlowOperation> _pageCanceled;
        private readonly UniTaskCompletionSource _cleanup = new();
        private CancellationTokenRegistration _pageRegistration;
        private IAccountSession _pendingSession;
        private bool _pageRegistered;
        private bool _disposed;

        internal RoomFlowOperation(CancellationToken rootToken, Action<RoomFlowOperation> pageCanceled)
        {
            _cancellation = rootToken.CanBeCanceled
                ? CancellationTokenSource.CreateLinkedTokenSource(rootToken)
                : new CancellationTokenSource();
            _pageCanceled = pageCanceled ?? throw new ArgumentNullException(nameof(pageCanceled));
        }

        internal RoomFlowPhase Phase { get; private set; }
        internal bool Invalidated { get; private set; }
        internal bool Submitted => Phase != RoomFlowPhase.Requesting;
        internal bool RecoverySuppressed { get; private set; }
        internal bool CleanupDone { get; private set; }
        internal bool ReleaseObserved { get; set; }
        internal MetaJoin Join { get; private set; }
        internal CancellationToken Token => _cancellation.Token;
        internal UniTask CleanupTask => _cleanup.Task;

        /// <summary>登记页面取消：只在 Requesting 阶段生效，入队前必须解除。</summary>
        internal void AttachPage(CancellationToken pageToken)
        {
            if (!pageToken.CanBeCanceled || _pageRegistered) return;
            _pageRegistered = true;
            _pageRegistration = pageToken.Register(
                static state => ((RoomFlowOperation)state).OnPageCanceled(), this);
        }

        /// <summary>解除页面取消注册（已接受的操作不再随页面隐藏取消）。</summary>
        internal void DetachPage()
        {
            if (!_pageRegistered) return;
            _pageRegistered = false;
            _pageRegistration.Dispose();
            _pageRegistration = default;
        }

        internal void MarkQueuedMatch(MetaJoin join)
        {
            Join = join;
            Phase = RoomFlowPhase.QueuedMatch;
        }

        internal bool TryMarkJoining(out MetaJoin join)
        {
            join = default;
            if (Invalidated || Phase != RoomFlowPhase.QueuedMatch) return false;
            Phase = RoomFlowPhase.Joining;
            join = Join;
            return true;
        }

        internal void MarkQueuedBattle(IAccountSession session)
        {
            _pendingSession = session;
            Phase = RoomFlowPhase.QueuedBattle;
        }

        internal IAccountSession TakePendingSession()
        {
            IAccountSession session = _pendingSession;
            _pendingSession = null;
            return session;
        }

        internal void MarkRunning() => Phase = RoomFlowPhase.Running;

        internal void MarkCleaning() => Phase = RoomFlowPhase.Cleaning;

        internal void MarkCleaned()
        {
            if (CleanupDone) return;
            Phase = RoomFlowPhase.Cleaned;
            CleanupDone = true;
            _cleanup.TrySetResult();
        }

        internal void Invalidate()
        {
            if (Invalidated) return;
            Invalidated = true;
            try { _cancellation.Cancel(); }
            catch (ObjectDisposedException) { }
        }

        internal void SuppressRecovery() => RecoverySuppressed = true;

        private void OnPageCanceled() => _pageCanceled(this);

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            DetachPage();
            try { _cancellation.Cancel(); }
            catch (ObjectDisposedException) { }
            _cancellation.Dispose();
            TakePendingSession()?.Dispose();
        }
    }
}

using System;
using System.Threading;

namespace LiteGame
{
    /// <summary>
    /// 每实例共享的房间操作寿命：唯一当前操作、排队/接管、清理通知与恢复抑制；不做页面导航。
    /// </summary>
    internal sealed class RoomFlowLifetime : IDisposable
    {
        private readonly CancellationToken _rootToken;
        private readonly CancellationTokenRegistration _rootRegistration;
        private RoomFlowOperation _current;
        private bool _disposed;

        internal RoomFlowLifetime(CancellationToken rootToken = default)
        {
            _rootToken = rootToken;
            if (rootToken.CanBeCanceled)
                _rootRegistration = rootToken.Register(
                    static state => ((RoomFlowLifetime)state).SuppressAndCancel(), this);
        }

        internal RoomFlowOperation Current => _current;
        internal bool IsBusy => _current != null;
        internal bool IsDisposed => _disposed;

        /// <summary>占用本实例并返回新操作句柄（调用方保证当前空闲）。</summary>
        internal RoomFlowOperation Begin()
        {
            if (_disposed) throw new ObjectDisposedException(nameof(RoomFlowLifetime));
            var operation = new RoomFlowOperation(_rootToken, OnPageCanceled);
            _current = operation;
            return operation;
        }

        internal bool IsCurrent(RoomFlowOperation operation)
            => !_disposed && ReferenceEquals(_current, operation);

        internal void AttachPage(RoomFlowOperation operation, CancellationToken pageToken)
            => operation?.AttachPage(pageToken);

        internal void DetachPage(RoomFlowOperation operation)
            => operation?.DetachPage();

        /// <summary>同步抑制旧恢复（登出/宿主关闭），后续 Leave 不清除该许可。</summary>
        internal void SuppressRecovery() => _current?.SuppressRecovery();

        /// <summary>使当前操作失效；Requesting 无已接受副作用可立即释放占用。</summary>
        internal RoomFlowOperation InvalidateCurrent(bool releaseRequesting)
        {
            RoomFlowOperation operation = _current;
            if (operation == null) return null;

            if (releaseRequesting && operation.Phase == RoomFlowPhase.Requesting)
            {
                _current = null;
                operation.Invalidate();
                operation.MarkCleaned();
                return operation;
            }

            operation.Invalidate();
            if (operation.Phase == RoomFlowPhase.QueuedBattle)
            {
                try { operation.TakePendingSession()?.Dispose(); }
                finally { operation.MarkCleaned(); }
            }
            return operation;
        }

        /// <summary>Match 实际入场：原子验活并一次接管排队参数；无效排队在这里被消费。</summary>
        internal bool TryConsumeMatch(RoomFlowOperation operation, out MetaJoin join)
        {
            join = default;
            if (!ReferenceEquals(_current, operation)) return false;
            if (operation.Phase != RoomFlowPhase.QueuedMatch) return false;

            if (operation.Invalidated)
            {
                _current = null;
                operation.MarkCleaned();
                return false;
            }

            join = operation.Join;
            operation.MarkJoining();
            return true;
        }

        /// <summary>JoinAck 后把会话托管给操作句柄，等待 Battle 实际接管；失败时调用方仍持有会话。</summary>
        internal bool TryQueueBattle(RoomFlowOperation operation, IAccountSession session)
        {
            if (session == null) throw new ArgumentNullException(nameof(session));
            if (!ReferenceEquals(_current, operation)
                || operation.Invalidated
                || operation.Phase != RoomFlowPhase.Joining)
                return false;

            operation.MarkQueuedBattle(session);
            return true;
        }

        /// <summary>Battle 实际接管：取得会话并进入 Running；无效排队不交出会话。</summary>
        internal bool TryTakeSession(RoomFlowOperation operation, out IAccountSession session)
        {
            session = null;
            if (!ReferenceEquals(_current, operation)
                || operation.Invalidated
                || operation.Phase != RoomFlowPhase.QueuedBattle)
                return false;

            session = operation.TakePendingSession();
            if (session == null) return false;
            operation.MarkRunning();
            return true;
        }

        internal void BeginCleanup(RoomFlowOperation operation)
        {
            if (ReferenceEquals(_current, operation)) operation.MarkCleaning();
        }

        /// <summary>阶段清理完成（会话/视图/卸载收口后由执行体调用）。</summary>
        internal void NotifyCleaned(RoomFlowOperation operation)
        {
            if (ReferenceEquals(_current, operation)) operation.MarkCleaned();
        }

        /// <summary>释放占用：只接受当前句柄且清理已完成；调用方须先确认 Main 条件。</summary>
        internal bool Release(RoomFlowOperation operation)
        {
            if (!ReferenceEquals(_current, operation)) return false;
            if (!operation.CleanupDone) return false;
            _current = null;
            return true;
        }

        internal void AbandonQueued(RoomFlowOperation operation)
        {
            if (!ReferenceEquals(_current, operation)) return;
            _current = null;
            operation.MarkCleaned();
        }

        private void OnPageCanceled(RoomFlowOperation operation)
        {
            if (!ReferenceEquals(_current, operation)) return;
            if (operation.Phase != RoomFlowPhase.Requesting) return;
            _current = null;
            operation.Invalidate();
            operation.MarkCleaned();
        }

        private void SuppressAndCancel()
        {
            _current?.SuppressRecovery();
            InvalidateCurrent(releaseRequesting: true);
        }

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            _rootRegistration.Dispose();
            RoomFlowOperation operation = _current;
            _current = null;
            if (operation == null) return;
            operation.SuppressRecovery();
            operation.Dispose();
        }
    }
}

using System;
using System.Threading;
using Cysharp.Threading.Tasks;
using LiteFramework;
using MetaWire;

namespace LiteGame
{
    /// <summary>
    /// 流程域的房间动作实现：单操作占用、取票/建房、票据校验与 Match 排队；不持 Meta 具体服务。
    /// </summary>
    internal sealed class ProcedureFlow : IRoomFlow, IAccountSessionControl, IDisposable
    {
        private const string BusyCode = "room.flow-busy";
        private const string InvalidCode = "room.flow-invalid";

        private readonly IStageHost<ProcedureId, ProcedureArgs> _machine;
        private readonly IRoomTicketSource _tickets;
        private readonly RoomFlowLifetime _lifetime;
        private readonly CancellationToken _rootToken;
        private bool _disposed;

        internal ProcedureFlow(IStageHost<ProcedureId, ProcedureArgs> machine, IRoomTicketSource tickets,
            RoomFlowLifetime lifetime, CancellationToken rootToken = default)
        {
            _machine = machine ?? throw new ArgumentNullException(nameof(machine));
            _tickets = tickets ?? throw new ArgumentNullException(nameof(tickets));
            _lifetime = lifetime ?? throw new ArgumentNullException(nameof(lifetime));
            _rootToken = rootToken;
        }

        public string AccountId => _tickets.AccountId;

        public bool IsLoggedIn => _tickets.IsLoggedIn;

        public UniTask<MetaCall<JoinTicketInfo>> EnterRoomAsync(string roomId, CancellationToken ct = default)
            => EnterCoreAsync(roomId, 0, 0, null, null, create: false, ct);

        public UniTask<MetaCall<JoinTicketInfo>> CreateRoomAsync(int mapId = 0, int expectedPlayers = 0,
            CancellationToken ct = default)
            => EnterCoreAsync(string.Empty, mapId, expectedPlayers, null, null, create: true, ct);

        public UniTask<MetaCall<JoinTicketInfo>> CreateRoomAsync(int mapId, int expectedPlayers,
            string template, string gmKey, CancellationToken ct = default)
            => EnterCoreAsync(string.Empty, mapId, expectedPlayers, template, gmKey, create: true, ct);

        /// <summary>离房：先使当前操作失效；Main 排队只由 Match 消费，不在 OnLeave/重入窗口反向 Request。</summary>
        public bool LeaveMatch()
        {
            ThrowIfDisposed();
            RoomFlowOperation operation = _lifetime.Current;
            bool hadOperation = operation != null;
            if (hadOperation) _lifetime.InvalidateCurrent(releaseRequesting: true);

            if (!_machine.Started) return hadOperation;

            if (_machine.Current == ProcedureId.Main)
            {
                if (hadOperation) ObserveRelease(operation);
                return hadOperation;
            }

            if (hadOperation) ObserveRelease(operation);
            _machine.Request(ProcedureId.Main);
            return true;
        }

        /// <summary>登出：先同步抑制旧恢复许可，再取消在途操作，最后委托票据源清登录态。</summary>
        public void Logout(string reason)
        {
            ThrowIfDisposed();
            _lifetime.SuppressRecovery();
            _lifetime.InvalidateCurrent(releaseRequesting: true);
            _tickets.Logout(reason);
        }

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            _lifetime.Dispose();
        }

        private async UniTask<MetaCall<JoinTicketInfo>> EnterCoreAsync(string roomId, int mapId,
            int expectedPlayers, string template, string gmKey, bool create, CancellationToken ct)
        {
            ThrowIfDisposed();
            ct.ThrowIfCancellationRequested();
            if (_machine.Current != ProcedureId.Main || _lifetime.IsBusy) return Busy();

            RoomFlowOperation operation = _lifetime.Begin();
            _lifetime.AttachPage(operation, ct);
            try
            {
                MetaCall<JoinTicketInfo> call = create
                    ? await CreateTicketAsync(operation, mapId, expectedPlayers, template, gmKey)
                    : await _tickets.RequestJoinTicketAsync(roomId, operation.Token);

                ct.ThrowIfCancellationRequested();
                operation.Token.ThrowIfCancellationRequested();
                if (!_lifetime.IsCurrent(operation))
                    throw new OperationCanceledException(operation.Token);
                if (!call.Ok) return call;

                if (!_tickets.IsConfigured || !_tickets.IsLoggedIn
                    || string.IsNullOrEmpty(_tickets.AccountId))
                    return Invalid();

                if (!RoomEndpoint.TryParse(call.Value.Address, out RoomEndpoint endpoint, out string reason))
                    return MetaCall<JoinTicketInfo>.Failed(
                        MetaFailure.Invalid("票据地址不可解析（" + reason + "）——联系部署侧核对 AdvertiseHost"));

                if (_machine.Current != ProcedureId.Main) return Busy();

                _lifetime.DetachPage(operation);
                var join = new MetaJoin(endpoint.Host, endpoint.Port, call.Value.RoomId, call.Value.Ticket);
                operation.MarkQueuedMatch(join);
                try
                {
                    _machine.Request(ProcedureId.Match,
                        new ProcedureArgs(metaJoin: join).WithRoomOperation(operation));
                }
                catch (InvalidOperationException)
                {
                    _lifetime.AbandonQueued(operation);
                    return Invalid();
                }
                return call;
            }
            finally
            {
                if (!operation.Submitted && _lifetime.IsCurrent(operation))
                    _lifetime.InvalidateCurrent(releaseRequesting: true);
            }
        }

        private UniTask<MetaCall<JoinTicketInfo>> CreateTicketAsync(RoomFlowOperation operation,
            int mapId, int expectedPlayers, string template, string gmKey)
            => template == null && gmKey == null
                ? _tickets.CreateRoomTicketAsync(mapId, expectedPlayers, operation.Token)
                : _tickets.CreateRoomTicketAsync(mapId, expectedPlayers, template, gmKey, operation.Token);

        private void ObserveRelease(RoomFlowOperation operation)
        {
            if (operation.ReleaseObserved) return;
            operation.ReleaseObserved = true;
            ReleaseAfterCleanupAsync(operation).ForgetLogged("ProcedureFlow");
        }

        /// <summary>清理完成且阶段已回 Main 后释放占用；不在取消/OnLeave 回调窗口内请求阶段。</summary>
        private async UniTask ReleaseAfterCleanupAsync(RoomFlowOperation operation)
        {
            await operation.CleanupTask;
            while (!_rootToken.IsCancellationRequested && !_disposed
                && _lifetime.IsCurrent(operation)
                && _machine.Started
                && _machine.Current != ProcedureId.Main)
            {
                await UniTask.Yield();
            }

            if (_rootToken.IsCancellationRequested || _disposed) return;
            _lifetime.Release(operation);
        }

        private static MetaCall<JoinTicketInfo> Busy()
            => MetaCall<JoinTicketInfo>.Failed(
                MetaFailure.Rejected(0, BusyCode, "入场操作进行中（取票/排队/接管/清理）"));

        private static MetaCall<JoinTicketInfo> Invalid()
            => MetaCall<JoinTicketInfo>.Failed(
                MetaFailure.Rejected(0, InvalidCode, "入场请求已失效（取消/登录态变化/阶段不允许）"));

        private void ThrowIfDisposed()
        {
            if (_disposed) throw new ObjectDisposedException(nameof(ProcedureFlow));
        }
    }
}

